def get_compact_shape_flat(grid, color):
    """Get pixels for color within grid and compact as list of lists"""
    pixels = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]
    if not pixels:
        return []

    min_r, min_c = min(p[0] for p in pixels), min(p[1] for p in pixels)
    max_r, max_c = max(p[0] for p in pixels), max(p[1] for p in pixels)

    height = max_r - min_r + 1
    width = max_c - min_c + 1

    result = [[0]*width for _ in range(height)]
    for r, c in pixels:
        result[r - min_r][c - min_c] = color
    return result

